"""Apply the source exclusion policy to documentation, notebook and UI."""
from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[1]

def update():
    root=ROOT
    for p in (root/'code').glob('*.md'):
        s=p.read_text()
        if p.name=='04_Revenue_Growth_Methodology.md':
            s='\n'.join(x for x in s.splitlines() if not x.startswith('| WRDS |'))+'\n'
            s=re.sub(r'\n\n\*\*Source restriction:\*\*[^\n]+','',s)
            s=s.replace('WRDS','excluded academic database')
            s=s.replace('**Proposed implementation plan | 15 November 2026 | Not an executed or validated forecast**','**Proposed implementation plan | 15 November 2026 | Not an executed or validated forecast**\n\n**Source restriction:** No WRDS-delivered data, text, ratios, classifications, joins or derived results are eligible for this pipeline, exports or website. Reacquire needed facts independently from permitted original sources; never relabel the old database text as another provider. Other providers remain subject to their own access and redistribution rights.')
        else:
            s=s.replace('SEC/LSEG/WRDS/web','SEC/LSEG/official-web').replace('LSEG/WRDS/Capital IQ','LSEG/Capital IQ').replace('LSEG/WRDS/news/search','LSEG/news/search')
        p.write_text(s)
    # Remove obsolete completion claims; all counts are recomputed from clean records.
    (root/'code/Research_Completion_Status.md').write_text('''# Research completion status\n\nUpdated 15 November 2026. Restricted academic-database observations have been removed from current publication data. Fields without independent retained evidence are UNKNOWN. Old candidate baskets and scores are withdrawn because selection used the mixed-source corpus; they require a new allowed-source run.\n\nThe 560 permitted target-input records are retained. The growth document is a detailed implementation plan, not a completed company forecast. Extracted passages remain subject to entity, scope, date and semantic review.\n''')
    # Input adapters may not return old local rows with hidden restricted lineage.
    p=root/'code/public_entity_registry.py';s=p.read_text().replace('quarantine ambiguous WRDS joins','apply permitted-source identity and evidence checks')
    s=s.replace('import gzip,json','import gzip,json\nfrom source_policy import restricted')
    s=s.replace("return [r for r in rows if r.get('description_eligible_for_matching',True)] if eligible_only else rows", "rows=[r for r in rows if not restricted(r)]\n return [r for r in rows if r.get('description_eligible_for_matching',True)] if eligible_only else rows")
    p.write_text(s)
    for name in ['continue_evidence_quality_20261112.py','complete_evidence_pass_20261111.py','industry_standard_app.js','website_app.js']:
        p=root/'code'/name;s=p.read_text();s=s.replace('Compustat SIC|','').replace('WRDS|CAPITAL.?IQ|COMPUSTAT','CAPITAL.?IQ');p.write_text(s)
    p=root/'code/website_app.js';s=p.read_text()
    replacement="""async function showComps(){const p=state.profile,tid=p.comparison_target_id;if(!tid){$('content').innerHTML='<h2>Public Comps</h2><p>'+word('Choose an original target company to view its permitted comparison inputs.','选择原始目标公司查看允许使用的比较输入。')+'</p>';return;}if(!comparisonInputs)comparisonInputs=await read('comparison_inputs');const input=comparisonInputs[tid]||{},f=input.available_financials||{};$('content').innerHTML=`<h2>Public Comps</h2><article class="card"><h3>This is treated as pseudo-private · ${esc(input.target_name||p.name)}</h3><p>${word('Only official website business evidence and instructor-file revenue, EBITDA and debt are permitted.','仅允许官网业务证据及老师文件里的 revenue、EBITDA 和 debt。')}</p><div class="metrics">${['revenue','ebitda','debt'].map(k=>`<span><b>${esc(f[k]??'UNKNOWN')}</b>${esc(k)}</span>`).join('')}</div><p class="small">${esc(input.financial_provenance?.units||'Units require verification')} · ${esc(input.financial_provenance?.period||'Period requires verification')}</p></article><p class="notice">${word('Previous candidate lists and similarity scores have been withdrawn following the source-policy change. Re-selection and scoring from permitted evidence are pending; no replacement ranking is claimed.','来源政策变更后，旧候选列表与相似度评分已撤下。需要以允许来源重新选取和评分；目前不声称已生成替代排名。')}</p><p><a href="../code/04_Revenue_Growth_Methodology.md">${word('Five-year revenue, EBITDA and valuation forecast plan','五年收入、EBITDA及估值预测方案')}</a></p>`;}"""
    s,n=re.subn(r'^async function showComps\(\).*$',lambda m:replacement,s,flags=re.M);assert n==1,n
    # No stale source counts or old cache versions.
    s=s.replace('unified-public-research-20261030','allowed-sources-20261115')
    p.write_text(s)
    html=root/'website/index.html';h=html.read_text();h=re.sub(r'<script>.*?</script>',lambda m:'<script>\n'+s+'\n</script>',h,flags=re.S)
    h=h.replace('Original input files and complete CSVs are stored separately from this public viewer.','Source-restricted observations and dependent scores are excluded. Complete allowed-source CSVs are available in Releases.')
    html.write_text(h)
    # Build from the repository's canonical sources; never reimport archived local corpus.
    (root/'code/build_unified_research_site.py').write_text('''"""Build the viewer from the canonical, source-filtered repository snapshot."""\nfrom pathlib import Path\nimport re,subprocess\nfrom exclude_restricted_sources import validate\nP=Path(__file__).resolve().parent;R=P.parent\nvalidate()\njs=(P/'website_app.js').read_text()\nsubprocess.run(['node','--check',str(P/'website_app.js')],check=True)\np=R/'website/index.html';s=p.read_text()\ns,n=re.subn(r'<script>.*?</script>',lambda m:'<script>\\n'+js+'\\n</script>',s,flags=re.S)\nassert n==1\np.write_text(s)\nprint('Built and source-policy checked website')\n''')
    # Notebook is self-contained and reads the one consolidated delivery.
    def md(s):return {'cell_type':'markdown','metadata':{},'source':s.splitlines(True)}
    def code(s):return {'cell_type':'code','execution_count':None,'metadata':{},'outputs':[],'source':s.splitlines(True)}
    cells=[md('# Company research: permitted-source data workflow\n\nUse the instructor workbook, Capital IQ workbook and `Research_Data.csv.gz` from the latest Release. All restricted academic-database data and dependent rankings are excluded. No credentials are stored here. Other providers require their own authorized access; local access does not imply public redistribution permission.\n'),code('from pathlib import Path\nimport csv,json,gzip,os\nimport pandas as pd\ncsv.field_size_limit(2**31-1)\nDATA=Path("Research_Data.csv.gz")\nassert DATA.exists(), "Download the current Release CSV beside this notebook."\ndef records(dataset=None):\n    with gzip.open(DATA,"rt",encoding="utf-8-sig",newline="") as f:\n        for row in csv.DictReader(f):\n            if dataset is None or row["dataset"]==dataset:\n                yield row\ndef table(dataset):\n    return pd.DataFrame(json.loads(r["record_json"]) for r in records(dataset))\nfrom collections import Counter\nprint(Counter(r["dataset"] for r in records()))\n'),md('## View research, sources and permitted target inputs\nProfile rows preserve exact evidence text and source links. A missing value remains unknown. General and industry updates are separate record types linked by company ID. Scores withdrawn after the source change are not silently reused.\n'),code('profiles=table("Unified_Public_Research")\ndisplay(profiles[[c for c in ["key","name","main_filled","industry_filled"] if c in profiles]].head())\ninputs=table("Restricted_Target_Inputs")\ndisplay(inputs.head())\nif len(profiles):\n    profile=profiles.iloc[0].to_dict()\n    display(pd.DataFrame(profile.get("sources",{})).T)\n    display(pd.DataFrame(profile.get("evidence",{})).T)\n'),md('## Original workbooks\nOnly the two permitted supplied workbooks are inputs. Retain file, sheet and cell provenance for imported observations.\n'),code('for name in ["Company_List_for_Interns.xlsx","CapitalIQ_560.xlsx"]:\n    p=Path(name)\n    if p.exists():\n        print(name,pd.ExcelFile(p).sheet_names)\n'),md('## Source retrieval examples\nSEC supplies reported facts, not consensus estimates. LSEG refresh requires an authorized local session and separately entitled fields. Target SEC data is research-only; it is never an input to simulated-private matching or forecasts. Functions below do not run automatically.\n'),code('import requests\ndef fetch_sec_facts(cik):\n    contact=os.environ.get("SEC_USER_AGENT")\n    if not contact: raise RuntimeError("Configure your contact SEC_USER_AGENT locally.")\n    url=f"https://data.sec.gov/api/xbrl/companyfacts/CIK{int(cik):010d}.json"\n    response=requests.get(url,headers={"User-Agent":contact},timeout=60)\n    response.raise_for_status()\n    return {"source_url":url,"record":response.json()}\ndef fetch_lseg(instruments,fields):\n    import lseg.data as ld\n    ld.open_session()\n    try: return ld.get_data(universe=instruments,fields=fields)\n    finally: ld.close_session()\n'),md('## Rebuild and validate publication data\n`code/exclude_restricted_sources.py` filters source/evidence graphs, invalidates inherited claims, withdraws stale rankings and validates all compressed website payloads. `code/build_unified_research_site.py` refuses a contaminated snapshot. The five-year forecast design is in `code/04_Revenue_Growth_Methodology.md`; company forecasts are not yet executed.\n')]
    nb={'cells':cells,'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3'}},'nbformat':4,'nbformat_minor':5}
    (root/'Research_Workflow.ipynb').write_text(json.dumps(nb,ensure_ascii=False,indent=1))
    (root/'README.md').write_text('''# Barbara069 / Private Company Comparables Research\n\n**[Open the website](https://barbara069.github.io/Private-Company-Public-Comparables-Search/)** · [Code](code/) · [Latest downloads](https://github.com/Barbara069/Private-Company-Public-Comparables-Search/releases/latest)\n\nThis is the single repository for the website, research code, notebook and methodology.\n\n## Sources and downloads\n\nFrom the latest Release, place `Company_List_for_Interns.xlsx`, `CapitalIQ_560.xlsx` and `Research_Data.csv.gz` beside [Research_Workflow.ipynb](Research_Workflow.ipynb). Pandas reads the compressed CSV directly. The CSV includes permitted provider observations, company research, original evidence/source links, industry and growth records, and the 560 restricted target-input records.\n\n**WRDS-delivered data is excluded everywhere in the active publication pipeline.** Its text, ratios, classifications, identifiers and dependent results must not be reused or relabeled as another source. This also applies to Capital IQ/Compustat data obtained through that service. Independently supplied Capital IQ workbook content has separate provenance. Other data providers remain subject to their own access and redistribution terms; removal of one source does not grant rights to the rest.\n\nSources retained where independently available include official company websites, SEC disclosures, directly obtained LSEG observations, and the supplied instructor/Capital IQ workbooks. Missing evidence is UNKNOWN. No credentials are committed.\n\n## Methodology\n\n1. [General facets](code/01_General_Facets.md)\n2. [Industry facets](code/02_Industry_Facets.md)\n3. [Similarity scoring standard](code/03_Similarity_Scoring.md)\n4. [Five-year revenue, EBITDA and valuation forecast plan](code/04_Revenue_Growth_Methodology.md)\n\n## Current status\n\nThe source policy changed on 15 November 2026. Previous candidate baskets and scores were produced from a mixed-source corpus and have been withdrawn pending allowed-source re-selection and scoring. Surviving excerpts are not automatically semantically verified. Forecast methodology is specified; company forecasts are not yet executed or validated.\n\nThe website lives in `website/`; canonical code and documentation live in `code/`. The publication guard checks decompressed payloads and evidence references. Original permitted target inputs remain isolated from unrestricted public research.\n''')
    (root/'code/README.md').write_text('''# Research code\n\nPython 3 and Node.js are required for source filtering and viewer validation. The notebook additionally uses pandas, requests and openpyxl; direct LSEG retrieval needs its authorized SDK/session. No academic-database adapter is included.\n\nRun `python code/exclude_restricted_sources.py --validate` and `python code/build_unified_research_site.py` before publishing. These validate the decompressed website payloads and check JavaScript. `source_policy.py` is the shared exclusion gate. Original target website plus instructor revenue, EBITDA and debt are the only simulated-private model inputs.\n\nSource-extraction utilities describe research work; presence of code does not prove all fields were downloaded or verified. Current candidate ranking must be rebuilt from the source-filtered corpus.\n''')
    (root/'code/Repository_Consolidation.json').unlink(missing_ok=True)

if __name__=='__main__':update()
